update public.learning_paths
set
  title = 'Counterpoint',
  goal = 'Counterpoint',
  summary = 'Counterpoint is an advanced study of independent musical lines: how they sing, combine, imitate, invert, intensify, and create form. Students write species exercises, cantus firmi, two-voice studies, three- and four-voice textures, canons, inventions, and fugue materials while analyzing Renaissance and Baroque models. The course treats counterpoint as both discipline and musicianship: a way to hear intervals, control dissonance, shape melody, plan texture, and compose with motivic economy.',
  data = $ctrpjson${"slug": "counterpoint", "title": "Counterpoint", "description": "Counterpoint is an advanced study of independent musical lines: how they sing, combine, imitate, invert, intensify, and create form. Students write species exercises, cantus firmi, two-voice studies, three- and four-voice textures, canons, inventions, and fugue materials while analyzing Renaissance and Baroque models. The course treats counterpoint as both discipline and musicianship: a way to hear intervals, control dissonance, shape melody, plan texture, and compose with motivic economy.", "topics": [{"id": "51401355-71a1-406e-9d14-9d54afdeaa20", "type": "topic", "title": "Species Counterpoint: First Through Fifth", "description": "Species counterpoint gives students a controlled laboratory for line, consonance, dissonance, rhythm, and independence before they write freer contrapuntal textures.", "children": [{"id": "4077c236-25cb-43e7-9278-a8dad9181c5c", "type": "subtopic", "title": "First Species", "children": [{"id": "0fec2617-2aeb-4a55-b448-fbd1333c9134", "type": "concept", "title": "Perfect and imperfect consonances"}, {"id": "1f536a54-6487-4f66-990a-256fabd06f84", "type": "concept", "title": "Contrary, oblique, and similar motion"}, {"id": "4ca29fd0-0845-48a7-9d70-5b6ab3a74763", "type": "concept", "title": "Avoiding parallels and hidden fifths/octaves"}], "description": "Students learn the consonant skeleton that underlies contrapuntal stability."}, {"id": "a4b0824e-47ef-412f-b5ae-0ea46a5c1b18", "type": "subtopic", "title": "Second and Third Species", "children": [{"id": "430dedf5-a4ac-4d92-91e4-e9c5ce8aa339", "type": "concept", "title": "Passing tones and metric placement"}, {"id": "c3cd8dbf-b688-40eb-9e30-4e9996338754", "type": "concept", "title": "Two-against-one and four-against-one rhythm"}, {"id": "ef9753af-b997-4aec-a8e5-1f8c3b954b5c", "type": "concept", "title": "Contour, climax, and melodic pacing"}], "description": "The point is to animate a line while preserving control."}, {"id": "9b69f398-f483-4bba-82c9-51c3ee6c5eb4", "type": "subtopic", "title": "Fourth and Fifth Species", "children": [{"id": "ad4b9954-a27d-45a2-af17-f6402cf35561", "type": "concept", "title": "Preparation, suspension, resolution"}, {"id": "b5cd3fa2-b25e-421f-bebf-9abbf54a0b47", "type": "concept", "title": "Suspension chains"}, {"id": "b2767f53-8621-4430-b76a-260c7e3366f6", "type": "concept", "title": "Mixed rhythmic values and idiomatic flow"}], "description": "Students learn suspensions and florid combinations as expressive dissonance."}]}, {"id": "a30e62dc-f346-48c5-a9bb-2b9684d4823d", "type": "topic", "title": "Cantus Firmus Writing", "description": "A good cantus firmus teaches phrase shape, modal syntax, and contrapuntal possibility. Students learn to compose strong source lines rather than treating them as neutral homework prompts.", "children": [{"id": "ded91c7d-374f-42b4-bb4b-37493a069c79", "type": "subtopic", "title": "Modal Profile", "children": [{"id": "10ff5017-9b92-415f-ba0f-10f714ea7633", "type": "concept", "title": "Final, range, reciting tone, and modal color"}, {"id": "5099d12c-3078-4def-8263-241f0ef58a78", "type": "concept", "title": "Leaps balanced by stepwise recovery"}, {"id": "ca8b546b-56fc-46b7-9d5b-84a551799ecd", "type": "concept", "title": "One clear melodic high point"}], "description": "Students shape lines within a mode while preserving singability."}, {"id": "931c61e0-231f-4898-ac16-a280364299a9", "type": "subtopic", "title": "Cadence and Closure", "children": [{"id": "ad68b4dd-ee60-4217-a769-ed9d521072e3", "type": "concept", "title": "Approach to final"}, {"id": "9f95e067-cfc5-4a63-9486-79e2ec7370a8", "type": "concept", "title": "Penultimate motion"}, {"id": "b90424c5-48ec-4964-8820-e2020777570a", "type": "concept", "title": "Avoiding premature closure"}], "description": "The cantus must imply a directed phrase."}, {"id": "5925327e-e5e3-474b-8c85-c504154ce85f", "type": "subtopic", "title": "Usability for Counterpoint", "children": [{"id": "23b4781e-0d4d-4d3b-889b-735de81af751", "type": "concept", "title": "Avoiding awkward repeated patterns"}, {"id": "8fccc08b-6fd3-4ef5-a383-361885ee2110", "type": "concept", "title": "Leaving room for contrary motion"}, {"id": "1591bc2f-5fbf-4e16-b337-87b54a01e895", "type": "concept", "title": "Checking cadence options"}], "description": "Students test whether a cantus supports strong added voices."}]}, {"id": "ab67feea-c786-497f-9e6c-e6cecee13891", "type": "topic", "title": "Two-Voice Counterpoint", "description": "Two voices expose every choice. Students learn independence, balance, motivic relationship, and harmonic implication with no textural hiding place.", "children": [{"id": "b35c2160-8a83-49f9-968d-a680234ff1c1", "type": "subtopic", "title": "Line Independence", "children": [{"id": "2bd2e638-2cb2-4a24-8f12-1c456da3f902", "type": "concept", "title": "Melodic contour in each voice"}, {"id": "140ba24c-297b-49a0-ad98-b50f19a21b76", "type": "concept", "title": "Registral separation and crossing"}, {"id": "a03a1bcc-748e-4e02-9ee5-4016fdb1e95e", "type": "concept", "title": "Rhythmic differentiation"}], "description": "Each voice must sing convincingly while forming a coherent whole."}, {"id": "a57a9b8c-ae96-497e-999c-471ca1a538e4", "type": "subtopic", "title": "Interval and Motion Control", "children": [{"id": "4bcd4941-b5c9-4ae0-8e0b-29a4fa846747", "type": "concept", "title": "Consonance/dissonance categories"}, {"id": "50f188b5-5293-4786-922c-95d6cb50a830", "type": "concept", "title": "Direct, contrary, similar, and oblique motion"}, {"id": "15570e71-2b19-4771-a10f-f24d278c42af", "type": "concept", "title": "Cadential intervals"}], "description": "Students manage the vertical result of horizontal lines."}, {"id": "8ef85557-cc87-4fff-a028-e06bebc7e17e", "type": "subtopic", "title": "Motivic Imitation", "children": [{"id": "bb19c202-cdcd-40eb-83cf-be9787d67119", "type": "concept", "title": "Short motives"}, {"id": "7233f3a4-0572-48e2-ba48-4d8deb2c89fd", "type": "concept", "title": "Imitation at octave/fifth/fourth"}, {"id": "776ebb25-f002-4dc3-b4ac-aec6631a4e50", "type": "concept", "title": "Sequence and transformation"}], "description": "The unit moves from rules toward composition."}]}, {"id": "b8af6c27-48b9-45fc-a48d-f2bdc70f70b0", "type": "topic", "title": "Three- and Four-Voice Counterpoint", "description": "Additional voices create richer harmony and greater risk. Students learn spacing, hierarchy, density, cadence, and the discipline of every line.", "children": [{"id": "5578847b-6501-4164-a4df-77737341f780", "type": "subtopic", "title": "Texture and Spacing", "children": [{"id": "f21c1b82-734a-4191-ab01-050348d78b13", "type": "concept", "title": "Upper/lower voice spacing"}, {"id": "dc095c77-7d87-4f0f-8f72-f4ef6dcd6800", "type": "concept", "title": "Voice crossing and overlap"}, {"id": "ddb16209-83c8-4554-bb32-44afccb32b22", "type": "concept", "title": "Doubling and register management"}], "description": "Students organize voices so the texture stays transparent."}, {"id": "3118e0b9-0e07-46e3-b92d-321fcf906330", "type": "subtopic", "title": "Voice Hierarchy", "children": [{"id": "29b0bf3e-fcdb-4b15-a0cd-4e046346eb3d", "type": "concept", "title": "Primary line, countersubject, filler, and cadential support"}, {"id": "d29e8f47-785c-47e1-adb0-14540ccc1958", "type": "concept", "title": "Alternating activity among voices"}, {"id": "ae734e62-de2f-4b75-811c-4fba4851c3a9", "type": "concept", "title": "Avoiding inert inner voices"}], "description": "Not every line carries the same role at every moment."}, {"id": "9238fa7e-fae8-416e-835d-4459070116dd", "type": "subtopic", "title": "Cadential Design", "children": [{"id": "35d14c23-5786-469f-8181-1022a6aafec3", "type": "concept", "title": "Approach tones"}, {"id": "eb0c4801-2218-482d-99ea-aa5c6d431ef2", "type": "concept", "title": "Suspensions at cadences"}, {"id": "2c694f6b-6feb-4abf-aa68-c5c6f18255ef", "type": "concept", "title": "Modal and tonal cadence types"}], "description": "Cadences require coordinated contrapuntal and harmonic arrival."}]}, {"id": "d6d4648f-6c3e-4e54-8aa9-7982be36a99b", "type": "topic", "title": "Invertible Counterpoint", "description": "Invertible counterpoint teaches composers to plan lines that remain valid when voices exchange positions, a core skill for canon, invention, and fugue.", "children": [{"id": "0179b3f3-5264-4d59-a48b-eb5239ee26b0", "type": "subtopic", "title": "Interval Planning", "children": [{"id": "c8cc329b-e1ad-403e-bfe9-58a38acc57f0", "type": "concept", "title": "Double counterpoint at octave, tenth, and twelfth"}, {"id": "3c9436e5-8041-4acc-8133-71ee11a80965", "type": "concept", "title": "Consonance changes under inversion"}, {"id": "155a5552-4b09-4012-a44b-d3f4c49eda9f", "type": "concept", "title": "Avoiding problematic fourths and dissonances"}], "description": "Students learn which intervals invert cleanly."}, {"id": "8909df8e-85c2-41c0-9fe4-9342ad48140e", "type": "subtopic", "title": "Contrapuntal Skeletons", "children": [{"id": "bb02afa4-c0fd-4176-99b6-2ebdccfe7b3a", "type": "concept", "title": "Outer-voice framework"}, {"id": "3a1aefa1-b41f-4c7b-b32c-fe3218314ffe", "type": "concept", "title": "Voice exchange"}, {"id": "e9558e00-2b70-41fa-bbf7-2862e0233ce9", "type": "concept", "title": "Reduction and recomposition"}], "description": "The goal is to design durable frameworks before ornamenting."}, {"id": "88d3abcc-3f88-4e4d-9958-09b1ab13d19d", "type": "subtopic", "title": "Applications", "children": [{"id": "bc1ba9dd-5e9f-4669-9058-2b8ba062f6f3", "type": "concept", "title": "Invertible subject/countersubject pairs"}, {"id": "e74b48b0-5916-451d-b195-c129314f2721", "type": "concept", "title": "Episode material"}, {"id": "f6bec6e8-37de-417b-a1a2-5d0c8ddb80ec", "type": "concept", "title": "Reversible sequences"}], "description": "Students apply inversion to real textures."}]}, {"id": "f38b2b17-ef4d-409e-a74a-08464415e56d", "type": "topic", "title": "Canon", "description": "Canon trains strict imitation, planning, and musical imagination under constraint. Students learn that rule-bound writing can still be expressive.", "children": [{"id": "6fe9f812-e370-433e-875f-26af11eb2d91", "type": "subtopic", "title": "Imitative Design", "children": [{"id": "0a3fc173-c451-45f9-9132-be805b02ec5d", "type": "concept", "title": "Time distance"}, {"id": "a193f7e3-17ea-45b3-b69f-da29daf65115", "type": "concept", "title": "Interval of imitation"}, {"id": "5d0a8f13-27f8-4b46-bd21-7706de16ca05", "type": "concept", "title": "Cadence coordination"}], "description": "Students plan leader/follower relationships."}, {"id": "76688fe8-5ab3-4fe9-9ad0-936c45a8a139", "type": "subtopic", "title": "Canon Types", "children": [{"id": "4a50a5e1-d1c9-477b-9fb6-c77ca472edf8", "type": "concept", "title": "Canon at the fifth/fourth"}, {"id": "2f11aea9-a220-48a1-b79d-3ea9d65a9775", "type": "concept", "title": "Augmentation and diminution"}, {"id": "207a97ac-510e-48d2-ac8c-497cf6f22272", "type": "concept", "title": "Mirror, crab, and puzzle canons"}], "description": "The course broadens beyond simple octave canon."}, {"id": "c5d584d7-eea6-471e-a78a-f22573b31161", "type": "subtopic", "title": "Musicality Under Constraint", "children": [{"id": "e24bf84e-04f8-44c2-80dc-139b5d4cf70e", "type": "concept", "title": "Phrase shape"}, {"id": "7d5c6413-5fac-48bb-8059-2779e3e2ae9c", "type": "concept", "title": "Harmonic direction"}, {"id": "ccfc6a26-36e1-4b5d-b8cc-c5a696c98be2", "type": "concept", "title": "Avoiding mechanical sequencing"}], "description": "Strictness must still sound musical."}]}, {"id": "183a481b-8430-4269-9e8f-36405c8c19de", "type": "topic", "title": "The Invention", "description": "The invention turns counterpoint into compact tonal argument. Students connect subject, sequence, episode, and motivic economy.", "children": [{"id": "0e07ab41-67d0-49df-a72e-502d1daeb956", "type": "subtopic", "title": "Subject and Countersubject", "children": [{"id": "7f8a59ee-709b-4808-b40f-e6