values
  ('51401355-71a1-406e-9d14-9d54afdeaa20', 'e0f1a2b3-4c5d-4e07-8a77-7b8c9d0e1f07', null, 'topic'::public.curated_course_node_type, 'Species Counterpoint: First Through Fifth', 'Species counterpoint gives students a controlled laboratory for line, consonance, dissonance, rhythm, and independence before they write freer contrapuntal textures.', 0),
  ('4077c236-25cb-43e7-9278-a8dad9181c5c', 'e0f1a2b3-4c5d-4e07-8a77-7b8c9d0e1f07', '51401355-71a1-406e-9d14-9d54afdeaa20', 'subtopic'::public.curated_course_node_type, 'First Species', 'Students learn the consonant skeleton that underlies contrapuntal stability.', 0),
