  ('b2767f53-8621-4430-b76a-260c7e3366f6', 'e0f1a2b3-4c5d-4e07-8a77-7b8c9d0e1f07', '9b69f398-f483-4bba-82c9-51c3ee6c5eb4', 'concept'::public.curated_course_node_type, 'Mixed rhythmic values and idiomatic flow', null, 2),
  ('a30e62dc-f346-48c5-a9bb-2b9684d4823d', 'e0f1a2b3-4c5d-4e07-8a77-7b8c9d0e1f07', null, 'topic'::public.curated_course_node_type, 'Cantus Firmus Writing', 'A good cantus firmus teaches phrase shape, modal syntax, and contrapuntal possibility. Students learn to compose strong source lines rather than treating them as neutral homework prompts.', 1),
