  ('1591bc2f-5fbf-4e16-b337-87b54a01e895', 'e0f1a2b3-4c5d-4e07-8a77-7b8c9d0e1f07', '5925327e-e5e3-474b-8c85-c504154ce85f', 'concept'::public.curated_course_node_type, 'Checking cadence options', null, 2),
