  ('776ebb25-f002-4dc3-b4ac-aec6631a4e50', 'e0f1a2b3-4c5d-4e07-8a77-7b8c9d0e1f07', '8ef85557-cc87-4fff-a028-e06bebc7e17e', 'concept'::public.curated_course_node_type, 'Sequence and transformation', null, 2),
